# Load definitions only; no repeated census.
exec(open('exact.py').read().split('stats={};')[0])
from itertools import combinations
rows=[]
for a in combinations(range(4,28),4):
 if reduce(gcd,a)!=1:continue
 w=apery(a)
 # truly minimal using the semigroup generated by other generators
 if any(inside(x,apery(tuple(y for y in a if y!=x))) for x in a if reduce(gcd,tuple(y for y in a if y!=x))==1):continue
 p=pf(a,w)
 if len(p)!=1:continue
 F=p[0]
 for alpha in range(1,F+1):
  if inside(alpha,w):continue
  h=F-alpha;z=facts(a,h)
  if len(z)<2:continue
  C=[x for x in range(F+1) if inside(x,w) and not inside(x+alpha,w)]
  D=[x for x in range(h+1) if inside(x,w) and inside(h-x,w)]
  assert C==D
  # Independent finite generator-minimality check via factorizations
  if any(len(facts(a,x))!=1 for x in a):continue
  M=[max(q[i] for q in z) for i in range(4)];T=[[j for j,b in enumerate(a) if inside((M[i]+1)*a[i]+alpha-b,w)] for i in range(4)]
  rows.append({'a':a,'PF':p,'alpha':alpha,'h':h,'Z_h':z,'M':M,'hprime':sum(x*y for x,y in zip(M,a)),'C_equals_D':C,'T':T});break
 if rows:break
assert rows
(root/'logs/route-result.json').write_text(json.dumps(rows,indent=2));print(json.dumps(rows,indent=2))
